from math import erf, exp, log, sqrt, pi, isnan

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    return K * exp(-r * T) * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

def norm_pdf(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def bs_greeks(S, K, r, sigma, T, kind="call", q=0.0):
    if T <= 0 or sigma <= 0:
        return {k: float("nan") for k in ("delta", "gamma", "vega", "theta", "rho")}
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    Sq, Kr = S * exp(-q * T), K * exp(-r * T)
    gamma = exp(-q * T) * norm_pdf(d1) / (S * sigma * sqrt(T))
    vega = Sq * norm_pdf(d1) * sqrt(T)
    decay = -Sq * norm_pdf(d1) * sigma / (2 * sqrt(T))
    if kind == "call":
        delta = exp(-q * T) * norm_cdf(d1)
        theta = decay - r * Kr * norm_cdf(d2) + q * Sq * norm_cdf(d1)
        rho = K * T * exp(-r * T) * norm_cdf(d2)
    elif kind == "put":
        delta = -exp(-q * T) * norm_cdf(-d1)
        theta = decay + r * Kr * norm_cdf(-d2) - q * Sq * norm_cdf(-d1)
        rho = -K * T * exp(-r * T) * norm_cdf(-d2)
    else:
        raise ValueError("kind must be 'call' or 'put'")
    return {"delta": delta, "gamma": gamma, "vega": vega, "theta": theta, "rho": rho}

